func strStr(haystack, needle string) int {
	if len(needle) == 0 {
		return 0
	}
	if len(needle) > len(haystack) {
		return -1
	}
	lps := make([]int, len(needle))
	for i, k := 1, 0; i < len(needle); i++ {
