type Fenwick struct {
	n    int
	tree []int
}

func NewFenwick(nums []int) *Fenwick {
	f := &Fenwick{n: len(nums), tree: make([]int, len(nums)+1)}
	for i, v := range nums {
		f.Add(i, v)
	}
	return f
}

func (f *Fenwick) Add(i, delta int) {
	for j := i + 1; j <= f.n; j += j & (-j) {
		f.tree[j] += delta
	}
}

func (f *Fenwick) Sum(l, r int) int {
	return f.prefix(r+1) - f.prefix(l)
}

func (f *Fenwick) prefix(i int) int {
	sum := 0
	for j := i; j > 0; j -= j & (-j) {
		sum += f.tree[j]
	}
	return sum
}
